func highestImageNum() int {
files, err := filepath.Glob(ORIGINAL_DIR + "/*")
if err != nil {
return 0
}
re := regexp.MustCompile(`/(\d+)`)
highest := 0
for _, file := range files {
matches := re.FindStringSubmatch(file)
if len(matches) > 1 {
num, err := strconv.Atoi(matches[1])
if err == nil && num > highest {
highest = num
}
}
}
return highest
}
